1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	const BASE_TYPE_ALLOWANCE = 3;
9	
10	const SPHINX_BASE_POINTS = 1;
11	
12	const MINIMUM_BONUS = 1;
13	
14	const POINTS_PER_EXTRA_TYPE = 2;
15	
16	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
17	
18	const distinctMonsterTypes = (cards: Card[]): Set<string> =>
19	  new Set(cards.map((card) => card.monster));
20	
21	// A Sphinx never counts itself, but it does count a fellow Sphinx — so the
22	// types any one Sphinx sees are the army's types, minus Sphinx unless a second
23	// Sphinx remains. Every Sphinx therefore sees the same number of types.
24	const typesSeenByEachSphinx = (army: Card[], sphinxCount: number): number => {
25	  const types = distinctMonsterTypes(army);
26	  if (sphinxCount < 2) types.delete(SPHINX);
27	  return types.size;
28	};
29	
30	const scoreOneSphinx = (typesSeen: number): number => {
31	  const extraTypes = typesSeen - BASE_TYPE_ALLOWANCE;
32	  const bonus =
33	    extraTypes > 0 ? POINTS_PER_EXTRA_TYPE * extraTypes : MINIMUM_BONUS;
34	  return SPHINX_BASE_POINTS + bonus;
35	};
36	
37	export const scoreArmy = (army: Card[]): number => {
38	  const sphinxCount = army.filter(isSphinx).length;
39	  return sphinxCount * scoreOneSphinx(typesSeenByEachSphinx(army, sphinxCount));
40	};
